import PropTypes from "prop-types";

const PdfHeader = ({findCompany}) => {

  PdfHeader.propTypes = {
    findCompany: PropTypes.string,
  };
  return {
    columns:[
      {
          image:'data:image/png;base64,',
             style: 'logo',width: 80,alignment: 'left',margin: [0, 10, 0, 0]
      },
      {
        stack: [
         
          {
            text: 'AMPRO PTE LTD',
            style: 'companyName', // Apply a style for h3
            alignment: 'center',
            margin: [0, 5, 0, 0], // Add some top margin
          },
          {
            text: 'WHOLESALER * IMPORTER * EXPORTER * GENERAL MERCHANTS',
            style: 'companySubtitleBold', // Apply a style for h6 bold
            alignment: 'center',
          },
          {
            text: `BLOCK B #02-01, 31 PENJURU LANE   SINGAPORE 609198`,
            style: 'companySubtitle', // Apply a style for h6
            alignment: 'center',
          },
          {
            text: `Tel : ${findCompany('cp.companyPhone') || 'N/A'}`, // Assuming you have a phone number setting
            style: 'companySubtitle', // Apply a style for h6
            alignment: 'center',
          },
          {
            text: `Email : ${findCompany('cp.companyEmail')}     Website : ${findCompany('cp.companyWebsite') || 'N/A'}`, // Assuming you have a website setting
            style: 'companySubtitle', // Apply a style for h6
            alignment: 'center',
          },
        ],
      },
    ],
    margin: [50, 20, 50, 10],
    styles: {
      logo: {}, // You can add logo specific styles here if needed
      companyName: {
        fontSize: 16, // Equivalent to h3 size
        bold: true,
      },
      companySubtitle: {
        fontSize: 10, // Equivalent to h6 size
      },
      companySubtitleBold: {
        fontSize: 10, // Equivalent to h6 size
        bold: true,
      },
    },
  };
};
export default PdfHeader
